"""Accessible interactive experiments for the extended curriculum (07–10)."""
def slider(key,label,lo,hi,step,value,unit=''):
    return f'<label for="{key}">{label}{unit}<input id="{key}" type="range" min="{lo}" max="{hi}" step="{step}" value="{value}"></label><output class="range-value" id="range-{key}">{value}</output>'
def select(key,label,options):
    return f'<label for="{key}">{label}<select id="{key}">'+''.join(f'<option value="{v}">{t}</option>' for v,t in options)+'</select></label>'
def check(key,label,checked=True):
    return f'<label class="lab-check"><input type="checkbox" id="{key}"{" checked" if checked else ""}> {label}</label>'
def shell(key,title,desc,controls,outputs,prompt):
    outs=''.join(f'<div><span>{label}</span><output id="out-{key}-{k}">—</output></div>' for k,label in outputs)
    return f'<section class="cosmo-lab" id="lab-{key}" aria-labelledby="lab-{key}-title"><div class="lab-heading"><span class="lab-kicker">Interactive experiment</span><h3 id="lab-{key}-title">{title}</h3><p>{desc}</p></div><div class="lab-controls">{controls}<button type="button" class="print-btn" data-reset="{key}">Reset experiment</button></div><div class="lab-outputs">{outs}</div><svg class="lab-canvas" id="plot-{key}" viewBox="0 0 680 330" role="img" aria-labelledby="plot-{key}-title"><title id="plot-{key}-title">{title}: interactive vector plot</title></svg><p class="lab-summary" id="summary-{key}" aria-live="polite"></p><div class="lab-prompt"><strong>Try this.</strong> {prompt}</div><p class="print-only lab-print-note">Snapshot of the experiment. Open the HTML edition to change the controls.</p><noscript><p class="lab-noscript">Enable JavaScript to use the experiment. The lecture and problems remain readable.</p></noscript></section>'

def windows():
    c=slider('win-t','Source temperature',1000,30000,100,5800,' [K]')+slider('win-z','Redshift z',0,5,.05,0)
    return shell('windows','Where does the light emerge, and can the ground see it?','A thermal source is shifted by redshift. The peak is only a guide: real sources also emit non-thermal radiation, and atmospheric windows are wavelength dependent.',c,[('rest','Rest-frame peak'),('obs','Observed peak'),('band','Band'),('photon','Photon energy at peak'),('access','Ground access')],'Increase z until an optical peak moves into the infrared. Why does this help high-redshift astronomy?')
def telescope():
    c=slider('tel-d','Aperture D',50,500,10,200,' [mm]')+slider('tel-f','Focal length',200,3000,50,1000,' [mm]')+slider('tel-e','Eyepiece focal length',4,40,1,20,' [mm]')+slider('tel-s','Seeing FWHM',.5,4,.1,1.5,' [arcsec]')
    return shell('telescope','Aperture, focal length and the atmosphere.','Diffraction sets a theoretical limit; seeing usually dominates from the ground. Magnification does not create resolution that the aperture and atmosphere did not provide.',c,[('fr','Focal ratio'),('mag','Magnification'),('pupil','Exit pupil'),('ray','Rayleigh limit'),('eff','Effective resolution'),('lim','Approx. limiting mag')],'Double the aperture. What happens to the diffraction limit and light grasp? Then make the exit pupil larger than a dark-adapted eye pupil.')
def root():
    c=slider('root-m','Mean anomaly M',0,360,1,60,' [deg]')+slider('root-e','Eccentricity e',0,.9,.01,.5)+select('root-method','Method',[('newton','Newton–Raphson'),('bisect','Bisection'),('fixed','Fixed-point')])
    return shell('root','Solve Kepler’s equation by iteration.','Solve M = E − e sin E for the eccentric anomaly E. Compare convergence speed and failure modes of three standard methods.',c,[('E','Eccentric anomaly E'),('res','Residual'),('iter','Iterations used'),('err','Change in last step')],'Set e near 0.9 and M near 0. Which method struggles? Why is a good initial guess valuable?')
def calculus():
    c=select('calc-f','Function',[('sin','sin x'),('gauss','e^(−x²)'),('poly','x²'),('lor','1/(1+x²)')])+slider('calc-x','Point x',-3,3,.05,1)+slider('calc-h','Step h',.001,.5,.001,.1)
    return shell('calculus','A derivative is a local slope; an integral is accumulated area.','Compare a numerical derivative and integral with the exact result for the selected function. The shaded area is the integral from 0 to x.',c,[('f','f(x)'),('df','Numerical derivative'),('exactdf','Exact derivative'),('int','Numerical integral'),('exactint','Exact integral')],'Make h very large, then very small. When does the derivative become inaccurate, and why?')
def vectors():
    c=slider('vec-a','Vector A magnitude',0,10,.1,5)+slider('vec-ta','A angle',0,360,1,20,' [deg]')+slider('vec-b','Vector B magnitude',0,10,.1,4)+slider('vec-tb','B angle',0,360,1,110,' [deg]')
    return shell('vectors','Add, project and rotate in two dimensions.','The parallelogram shows A+B. The dot product measures projection; the z-component of the cross product measures oriented area.',c,[('sum','A+B'),('mag','|A+B|'),('dot','A·B'),('cross','(A×B)z'),('angle','Angle between')],'Make the vectors perpendicular, then parallel. What happens to the dot and cross products?')
def geometry():
    c=slider('geo-scale','Plate scale',.5,10,.1,2,' [arcsec/mm]')+slider('geo-len','Measured length',1,80,.5,30,' [mm]')+slider('geo-pa','Position angle',0,360,1,45,' [deg]')
    return shell('geometry','Turn a ruler-and-protractor reading into sky components.','Position angle is measured from north through east. The plate scale converts millimetres on a chart into angular separation.',c,[('sep','Angular separation'),('dra','Δα cos δ'),('ddec','Δδ')],'Rotate the position angle to 90°. Which component vanishes? Why is the cos δ factor needed?')
def stats():
    c=slider('stat-n','Number of measurements',5,100,1,20)+slider('stat-s','Random scatter σ',.05,1,.05,.3)+slider('stat-o','Outlier offset',0,5,.1,0)
    return shell('stats','Mean, median, scatter and the effect of one bad point.','A fixed synthetic sample is drawn from a normal-like distribution. The last point can be shifted into an outlier. Compare robust and non-robust summaries.',c,[('mean','Mean'),('median','Median'),('std','Sample std dev'),('sem','Standard error'),('max','Largest deviation')],'Add a large outlier. Which summary moves more? Does increasing n remove a systematic offset?')
def nakedeye():
    c=slider('eye-lim','Limiting magnitude',1,6.5,.1,5)+slider('eye-rot','Field rotation',0,360,5,0,' [deg]')
    return shell('nakedeye','How many stars survive your sky?','A synthetic star field is filtered by limiting magnitude. Hand spans are rough angular rulers: one finger ≈ 1°, three fingers ≈ 5°, a fist ≈ 10°, a spread hand ≈ 20°.',c,[('count','Stars visible'),('bright','Brightest visible'),('hand','Fist widths across 60°')],'Lower the limiting magnitude from 6 to 3. Does the sky lose only a few stars, or most of them?')
def skymap():
    c=slider('map-lim','Catalogue magnitude limit',0,6,.1,4)+slider('map-ra','Chart centre RA',0,24,.5,6,' [h]')+slider('map-dec','Chart centre Dec',-60,90,5,20,' [deg]')
    return shell('skymap','Filter a catalogue and read a chart.','A small synthetic catalogue is plotted in equatorial coordinates. Marker size encodes brightness; the grid spacing is 2 h in RA and 20° in Dec.',c,[('count','Stars in chart'),('bright','Brightest in chart'),('field','Field width')],'Raise the magnitude limit. Why does the number of stars grow quickly? Move the chart centre to a sparse region.')
def coords():
    c=slider('coord-ra','Target RA',0,24,.1,6,' [h]')+slider('coord-dec','Target Dec',-90,90,1,20,' [deg]')+slider('coord-lst','Local sidereal time',0,24,.1,6,' [h]')+slider('coord-lat','Observer latitude',-90,90,1,47.9,' [deg]')
    return shell('coords','From catalogue coordinates to the local sky.','Hour angle H = LST − RA. Altitude and azimuth follow from spherical astronomy. Azimuth is measured from north through east.',c,[('ha','Hour angle'),('alt','Altitude'),('az','Azimuth'),('air','Airmass'),('state','Rise/set state')],'Set H = 0. Where is the object? Move the latitude and watch the circumpolar boundary change.')
def exposure():
    c=slider('exp-d','Aperture',50,500,10,200,' [mm]')+slider('exp-m','Target magnitude',6,16,.1,10)+slider('exp-t','Exposure',1,300,1,60,' [s]')+slider('exp-sky','Sky brightness',16,22,.1,19,' [mag/arcsec²]')
    return shell('exposure','Signal, sky and noise in one exposure.','A simplified photon-counting model uses a fixed zero point, 1 arcsec² photometric aperture, read noise and dark current. It is a planning tool, not a calibrated instrument model.',c,[('src','Source electrons'),('sky','Sky electrons'),('snr','Signal-to-noise'),('t5','Time for SNR = 5')],'Double the exposure. Does SNR double? Make the sky brighter and find the new exposure needed for SNR = 5.')
def errors():
    c=slider('err-true','True value',1,20,.1,10)+slider('err-bias','Systematic offset',-2,2,.05,.5)+slider('err-sig','Random scatter',.05,1,.05,.3)+slider('err-n','Number of readings',1,100,1,10)
    return shell('errors','Averaging beats random noise, not a wrong zero.','Repeated readings contain a fixed bias plus random scatter. The mean reduces random uncertainty as 1/√n but leaves a known bias unchanged; correct the bias before combining residual uncertainties.',c,[('mean','Expected mean'),('rand','Random uncertainty'),('total','RSS if bias is an uncertainty'),('bias','Remaining bias')],'Increase n to 100. Which part of the error shrinks? Set the bias to zero and repeat.')
def fit():
    c=slider('fit-slope','True slope',.5,5,.1,2)+slider('fit-noise','Noise σ',0,1,.05,.2)+slider('fit-n','Number of points',5,30,1,12)+check('fit-out','Include outlier',False)
    return shell('fit','Fit a line and inspect the residuals.','Synthetic data follow y = slope·x + 1 with Gaussian-like noise. The least-squares line, slope uncertainty and R² are computed live; a residual panel is drawn below the fit.',c,[('slope','Fitted slope'),('intercept','Fitted intercept'),('r2','R²'),('serr','Slope uncertainty')],'Turn on the outlier. How much do the slope and R² move? Why should you plot residuals, not only R²?')
def doublestar():
    c=slider('ds-sep','True separation',1,20,.1,8,' [arcsec]')+slider('ds-pa','True position angle',0,360,1,60,' [deg]')+slider('ds-scale','Plate scale',.5,5,.1,1,' [arcsec/mm]')+slider('ds-err','Reading error',0,2,.05,.5,' [mm]')
    return shell('doublestar','Measure a double star on a chart.','The companion is placed at a known separation and position angle. A ruler reading error is converted into an angular uncertainty using the plate scale.',c,[('mm','Ruler length'),('sep','Measured separation'),('unc','Angular uncertainty'),('pa','Position angle')],'Halve the plate scale k (arcsec/mm). What happens to the angular uncertainty for the same ruler error?')
def photometry():
    c=slider('ph-depth','Transit/eclipse depth',.01,.5,.01,.1)+slider('ph-phase','Orbital phase',0,1,.01,.25)+slider('ph-noise','Synthetic ripple amplitude',.001,.05,.001,.01)+slider('ph-comp','Comparison offset',-.2,.2,.01,0)
    return shell('photometry','Differential photometry cancels shared trends.','A synthetic eclipsing system is compared with a stable comparison star. The differential magnitude removes a common transparency trend, leaving the eclipse and deterministic synthetic ripple.',c,[('delta','Differential magnitude'),('model','Model magnitude'),('res','Residual'),('depth','Input depth scale')],'Move through phase 0 and 0.5. Where are the eclipses? Increase the comparison offset: does the differential curve shift?')
LABS={'windows':windows,'telescope':telescope,'root':root,'calculus':calculus,'vectors':vectors,'geometry':geometry,'stats':stats,'nakedeye':nakedeye,'skymap':skymap,'coords':coords,'exposure':exposure,'errors':errors,'fit':fit,'doublestar':doublestar,'photometry':photometry}
